package org.railtracker.fois;
import android.app.*;import android.os.*;import android.widget.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.text.Html;import android.content.Intent;import java.net.*;import java.io.*;import java.util.regex.*;
public class MainActivity extends Activity {
 LinearLayout root; EditText query, captcha; TextView result; ImageView image; boolean dark=false; String last=""; final String base="https://www.fois.indianrail.gov.in/FOISWebPortal"; final String page=base+"/pages/FWP_FNREnq.jsp"; boolean ready=false;
 int bg(){return dark?0xff10141c:0xffe8f1ff;} int fg(){return dark?0xffe9f2ff:0xff163453;}
 GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(28);return d;}
 TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(fg());t.setPadding(10,6,10,6);return t;}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(-1);b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x33ffffff),shape(0xff245baf),null));b.setElevation(0);b.setTextSize(13);b.setMinHeight(48);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,8,0,8);root.addView(b,p);b.setOnClickListener(v->r.run());}
 EditText field(String hint){EditText e=new EditText(this);e.setSingleLine();e.setHint(hint);e.setTextColor(fg());e.setHintTextColor(0xff8295ad);e.setPadding(24,18,24,18);e.setBackground(shape(dark?0xff202833:0xfff8fbff));root.addView(e);return e;}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(1024,1024);CookieHandler.setDefault(new CookieManager(null,CookiePolicy.ACCEPT_ORIGINAL_SERVER));draw();}
 void draw(){ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(28,64,28,32);root.setBackgroundColor(bg());sc.setFillViewport(true);sc.setBackgroundColor(bg());sc.addView(root);setContentView(sc);root.addView(label("FOIS  /  Rail Tracker",30));root.addView(label("Freight intelligence • Native enquiry",15));query=field("11-digit FNR or RMN CFS");query.setText(last.isEmpty()?getPreferences(0).getString("last_fnr",""):last);button("Search / Load verification",()->load());image=new ImageView(this);root.addView(image,new LinearLayout.LayoutParams(-1,130));captcha=field("Enter verification code");button("Get freight details",()->submit());button("Refresh verification",()->load());result=label("Enter a freight number to begin.",17);result.setTextIsSelectable(true);root.addView(result);button("Save FNR",()->{String n=query.getText().toString().trim();if(n.matches("[0-9]{11}")){remember(n);Toast.makeText(this,"FNR saved",Toast.LENGTH_SHORT).show();}});button("Saved FNR numbers",()->savedNumbers());button("Offline freight history",()->{String cached=getPreferences(0).getString("latest_output","");if(cached.isEmpty())show("No cached results");else fullResult(cached);});button("Share result",()->{Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,result.getText().toString());startActivity(Intent.createChooser(i,"Share freight details"));});button("Light / Dark mode",()->{last=query.getText().toString();dark=!dark;ready=false;draw();});}
 byte[] request(String url,String data)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setRequestProperty("Referer",page);if(data!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");try(OutputStream o=c.getOutputStream()){o.write(data.getBytes("UTF-8"));}}try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);return out.toByteArray();}finally{c.disconnect();}}
 void show(String s){runOnUiThread(()->result.setText(s));}
 void load(){last=query.getText().toString().trim();ready=false;captcha.setText("");image.setImageDrawable(null);if(!last.matches("[0-9]{11}")){show(last.matches("(?i)[a-z]{2,5} +[a-z]{2,5}")?"Station-pair enquiry requires an authorized ECBS session. Not implemented in this build.":"Enter a valid 11-digit FNR.");return;}show("Loading verification…");new Thread(()->{try{request(page,null);byte[] b=request(base+"/portalCaptcha.jpg?_="+System.currentTimeMillis(),null);Bitmap bmp=BitmapFactory.decodeByteArray(b,0,b.length);if(bmp==null)throw new IOException("Verification image unavailable");runOnUiThread(()->{image.setImageBitmap(bmp);ready=true;result.setText("Enter the verification code and tap Get freight details.");});}catch(Exception e){show("Connection failed: "+e.getMessage());}}).start();}
 String value(String output,String key){for(String line:output.split("\n")){String[] p=line.split("\\|",2);if(p.length==2&&p[0].trim().equalsIgnoreCase(key))return p[1].trim();}return "Not reported";}
 void remember(String n){java.util.Set<String> numbers=new java.util.HashSet<>(getPreferences(0).getStringSet("fnrs",java.util.Collections.emptySet()));numbers.add(n);getPreferences(0).edit().putStringSet("fnrs",numbers).putString("last_fnr",n).apply();}
 void savedNumbers(){String[] items=getPreferences(0).getStringSet("fnrs",java.util.Collections.emptySet()).toArray(new String[0]);java.util.Arrays.sort(items);if(items.length==0){show("No saved freight numbers");return;}new AlertDialog.Builder(this).setTitle("Saved freight numbers").setItems(items,(d,i)->{query.setText(items[i]);load();}).setNegativeButton("Close",null).show();}
 void card(LinearLayout parent,String heading,String body,int color){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(20,16,20,16);c.setBackground(shape(color));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,16);parent.addView(c,p);c.addView(label(heading,14));c.addView(label(body,heading.equals("EXPECTED ARRIVAL")?36:16));}
 void action(LinearLayout parent,String title,Runnable r){Button b=new Button(this);b.setAllCaps(false);b.setText(title);b.setTextColor(-1);b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x33ffffff),shape(0xff245baf),null));b.setElevation(0);b.setTextSize(13);b.setMinHeight(48);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(4,4,4,4);parent.addView(b,p);b.setOnClickListener(v->r.run());}
 void fullResult(String output){Dialog d=new Dialog(this,dark?android.R.style.Theme_Material_NoActionBar_Fullscreen:android.R.style.Theme_Material_Light_NoActionBar_Fullscreen);LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(24,24,24,16);panel.setBackgroundColor(bg());panel.addView(label("Freight movement",22));long stamp=getPreferences(0).getLong("updated_at",0);if(stamp>0)panel.addView(label("Last retrieved: "+java.text.DateFormat.getDateTimeInstance().format(new java.util.Date(stamp)),12));ScrollView scroll=new ScrollView(this);LinearLayout content=new LinearLayout(this);content.setOrientation(1);scroll.addView(content);panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));int surface=dark?0xff202833:0xfff8fbff;card(content,"FREIGHT ROUTE",value(output,"From")+"  →  "+value(output,"To"),surface);card(content,"EXPECTED ARRIVAL",value(output,"ETA At Destination"),dark?0xff253b56:0xffcde1ff);card(content,"CONSIGNMENT",output.split("\n")[0]+"\n"+value(output,"Detail"),surface);
 java.util.ArrayList<java.util.LinkedHashMap<String,String>> stops=new java.util.ArrayList<>();java.util.LinkedHashMap<String,String> current=null;for(String line:output.split("\n")){String[] p=line.split("\\|",2);if(p.length!=2)continue;String k=p[0].trim(),v=p[1].trim();if(k.equalsIgnoreCase("Station")){if(current==null||!v.equals(current.get("Station"))){current=new java.util.LinkedHashMap<>();current.put("Station",v);stops.add(current);}}else if(current!=null&&(k.equals("Arrival")||k.equals("Departure")||k.equals("Departure Time")||k.equals("Zone (Division)"))){current.put(k.equals("Departure Time")?"Departure":k,v);}}
 if(!stops.isEmpty()){java.util.Map<String,String> latest=stops.get(stops.size()-1);card(content,"LAST REPORTED STATION",latest.get("Station")+"\n"+latest.getOrDefault("Departure",latest.getOrDefault("Arrival","Time not reported")),dark?0xff164b39:0xffd5f4df);}
 content.addView(label("Journey timeline  •  "+stops.size()+" station records",20));for(int i=stops.size()-1;i>=0;i--){java.util.Map<String,String> st=stops.get(i);card(content,(i==stops.size()-1?"●  Latest reported":"○  Station "+(i+1)),st.get("Station")+"\n"+st.getOrDefault("Zone (Division)","")+"\nArrival: "+st.getOrDefault("Arrival","—")+"\nDeparture: "+st.getOrDefault("Departure","—"),i==stops.size()-1?(dark?0xff164b39:0xffd5f4df):surface);}
 LinearLayout actions=new LinearLayout(this);panel.addView(actions);action(actions,"Refresh",()->refreshInside(d,output));action(actions,"Save",()->{getPreferences(0).edit().putString("saved",output).apply();Toast.makeText(this,"Saved",Toast.LENGTH_SHORT).show();});action(actions,"Share",()->{Intent intent=new Intent(Intent.ACTION_SEND);intent.setType("text/plain");intent.putExtra(Intent.EXTRA_TEXT,output);startActivity(Intent.createChooser(intent,"Share freight details"));});LinearLayout bottom=new LinearLayout(this);panel.addView(bottom);action(bottom,"Back to search",()->d.dismiss());action(bottom,"Theme",()->{dark=!dark;d.dismiss();fullResult(output);});d.setContentView(panel);d.show();}
 void refreshInside(Dialog parent,String output){LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(24,16,24,16);ImageView pic=new ImageView(this);form.addView(pic,new LinearLayout.LayoutParams(-1,120));EditText code=new EditText(this);code.setHint("Verification code");form.addView(code);AlertDialog prompt=new AlertDialog.Builder(this,dark?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert).setTitle("Refresh freight details").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Update",null).create();prompt.show();prompt.getButton(-1).setEnabled(false);new Thread(()->{try{request(page,null);byte[] b=request(base+"/portalCaptcha.jpg?_="+System.currentTimeMillis(),null);Bitmap bmp=BitmapFactory.decodeByteArray(b,0,b.length);runOnUiThread(()->{if(bmp==null){code.setError("Verification unavailable");return;}pic.setImageBitmap(bmp);prompt.getButton(-1).setEnabled(true);});}catch(Exception e){runOnUiThread(()->code.setError("Connection failed"));}}).start();prompt.getButton(-1).setOnClickListener(v->{String entered=code.getText().toString().trim();if(entered.isEmpty()){code.setError("Required");return;}String fnr=output.split("\\n")[0].replace("FNR","").trim();prompt.dismiss();query.setText(fnr);last=fnr;captcha.setText(entered);ready=true;submit();});}
 void submit(){String fnr=query.getText().toString().trim(),code=captcha.getText().toString().trim();if(!ready||!fnr.equals(last)||code.isEmpty()){show("Load verification for this FNR first.");return;}ready=false;show("Fetching freight details…");new Thread(()->{try{String enc=URLEncoder.encode(code,"UTF-8");String response=new String(request(base+"/FWP_FNREnq","Qry=FNR_ENQUIRY&txtFNRNumb="+fnr+"&captchaText="+enc),"UTF-8");Matcher m=Pattern.compile("(?is)ETA At Destination</b>\\s*</td>\\s*<td[^>]*>(.*?)</td>").matcher(response);if(m.find()){StringBuilder details=new StringBuilder("FNR  "+fnr+"\n\n");Matcher rows=Pattern.compile("(?is)<tr[^>]*>(.*?)</tr>").matcher(response);while(rows.find()){Matcher cells=Pattern.compile("(?is)<t[dh][^>]*>(.*?)</t[dh]>").matcher(rows.group(1));StringBuilder row=new StringBuilder();while(cells.find()){String val=Html.fromHtml(cells.group(1),0).toString().trim();if(!val.isEmpty()){if(row.length()>0)row.append("  |  ");row.append(val);}}if(row.length()>0)details.append(row).append("\n\n");}String output=details.toString();show("Freight details ready.");remember(fnr);getPreferences(0).edit().putString("latest_output",output).putLong("updated_at",System.currentTimeMillis()).apply();runOnUiThread(()->fullResult(output));}else{show("No ETA returned. Check the FNR and refresh verification.");}}catch(Exception e){show("Enquiry failed: "+e.getMessage());}}).start();}
}